style.Why editorial container:
display: grid; gap: 40px; grid-template-columns: minmax(0,0.54fr) minmax(0,1fr); align-items: start;
@media(--tablet) { grid-template-columns: minmax(0,1fr); }
@media(--mobile) { gap: var(--space-lg); }
@media(--mobile) { display: flex; flex-direction: column; gap: var(--space-md); }

style.Why introduction column:
max-width: 420px; display: flex; flex-direction: column; align-content: start; align-self: stretch;
@media(--tablet) { max-width: 640px; }
@media(--mobile) { display: contents; }

style.Why benefits grid:
display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); align-items: stretch;
@media(--mobile) { grid-template-columns: minmax(0,1fr); }
@media(--mobile) { order: 1; margin-block-start: var(--space-xs); }
